import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_04_01_config_layers.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_04_02_memory_tiers.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_04_03_mcp_bridge.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_04_04_subagents.png",h="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_04_05_skills_disclosure.png",p="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_04_06_plugin_bundle.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_04_07_rules_hooks.png",P=JSON.parse('{"title":"给 Codex 装上外接大脑：配置、记忆、MCP、子代理、Skills 与插件全解","description":"当 AI 编程从偶尔试用变成日常生产，真正棘手的问题会从“它会不会写代码”转向“它能否长期按同一套规则工作”。模型每次都很聪明，却可能不知道团队约定；工具很多，却可能在不该调用时乱用；任务很大，却可能把不同上下文揉成一团。解决这些问题，靠的不是一条万能 Prompt，而是一套分层扩展体系。","frontmatter":{"title":"给 Codex 装上外接大脑：配置、记忆、MCP、子代理、Skills 与插件全解","description":"当 AI 编程从偶尔试用变成日常生产，真正棘手的问题会从“它会不会写代码”转向“它能否长期按同一套规则工作”。模型每次都很聪明，却可能不知道团队约定；工具很多，却可能在不该调用时乱用；任务很大，却可能把不同上下文揉成一团。解决这些问题，靠的不是一条万能 Prompt，而是一套分层扩展体系。","date":"2026-08-10","topic":"AI 底层学习","section":"Codex · 智能代理七章","readingTime":9,"source":"2026-08-10/ai_codex_04_memory_mcp_skills.md","status":"published","cover":"/article-assets/2026-08-10/ai_codex_04_01_config_layers.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-04-memory-mcp-skills"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"给 Codex 装上外接大脑：配置、记忆、MCP、子代理、Skills 与插件全解"}],["meta",{"property":"og:description","content":"当 AI 编程从偶尔试用变成日常生产，真正棘手的问题会从“它会不会写代码”转向“它能否长期按同一套规则工作”。模型每次都很聪明，却可能不知道团队约定；工具很多，却可能在不该调用时乱用；任务很大，却可能把不同上下文揉成一团。解决这些问题，靠的不是一条万能 Prompt，而是一套分层扩展体系。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-04-memory-mcp-skills"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_04_01_config_layers.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"给 Codex 装上外接大脑：配置、记忆、MCP、子代理、Skills 与插件全解"}],["meta",{"name":"twitter:description","content":"当 AI 编程从偶尔试用变成日常生产，真正棘手的问题会从“它会不会写代码”转向“它能否长期按同一套规则工作”。模型每次都很聪明，却可能不知道团队约定；工具很多，却可能在不该调用时乱用；任务很大，却可能把不同上下文揉成一团。解决这些问题，靠的不是一条万能 Prompt，而是一套分层扩展体系。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_04_01_config_layers.png"}]],"prev":{"text":"AI 为什么会越改越准：Prompt、上下文、沙箱与 Computer Use 的协作闭环","link":"/ai/ai-codex-03-interaction-loop"},"next":{"text":"从单兵助手到自动化流水线：Worktree、GitHub、codex exec 与 CI 实战","link":"/ai/ai-codex-05-engineering-automation"}},"headers":[],"relativePath":"ai/ai-codex-04-memory-mcp-skills.md","filePath":"ai/ai-codex-04-memory-mcp-skills.md","lastUpdated":null}'),d={name:"ai/ai-codex-04-memory-mcp-skills.md"};function _(m,a,k,u,x,b){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="给-codex-装上外接大脑-配置、记忆、mcp、子代理、skills-与插件全解" tabindex="-1">给 Codex 装上外接大脑：配置、记忆、MCP、子代理、Skills 与插件全解 <a class="header-anchor" href="#给-codex-装上外接大脑-配置、记忆、mcp、子代理、skills-与插件全解" aria-label="Permalink to &quot;给 Codex 装上外接大脑：配置、记忆、MCP、子代理、Skills 与插件全解&quot;">​</a></h1><p>当 AI 编程从偶尔试用变成日常生产，真正棘手的问题会从“它会不会写代码”转向“它能否长期按同一套规则工作”。模型每次都很聪明，却可能不知道团队约定；工具很多，却可能在不该调用时乱用；任务很大，却可能把不同上下文揉成一团。解决这些问题，靠的不是一条万能 Prompt，而是一套分层扩展体系。</p><p>本文归纳 Codex 系列第 18～24 篇，把配置、记忆、MCP、子代理、Skills、插件、规则与 Hooks 放到同一张架构图里。你会看到：它们分别解决默认行为、历史经验、外部连接、并行分工、流程封装、能力分发和动作治理，彼此相关却不能互相替代。</p><h2 id="一、配置决定代理的默认工作姿势" tabindex="-1">一、配置决定代理的默认工作姿势 <a class="header-anchor" href="#一、配置决定代理的默认工作姿势" aria-label="Permalink to &quot;一、配置决定代理的默认工作姿势&quot;">​</a></h2><h3 id="_1-1-配置不是项目知识" tabindex="-1">1.1 配置不是项目知识 <a class="header-anchor" href="#_1-1-配置不是项目知识" aria-label="Permalink to &quot;1.1 配置不是项目知识&quot;">​</a></h3><p>模型选择、推理强度、沙箱模式、批准策略和工具开关，属于运行配置；代码规范、构建命令和目录边界，属于项目知识。前者回答“代理怎样运行”，后者回答“在这个仓库怎样做事”。</p><p>把二者混在一起，会造成配置文件难以共享、项目规则无法随仓库版本演进。更清晰的做法是让运行配置保持通用，让 <code>AGENTS.md</code> 随项目维护。</p><h3 id="_1-2-分层配置要有明确覆盖关系" tabindex="-1">1.2 分层配置要有明确覆盖关系 <a class="header-anchor" href="#_1-2-分层配置要有明确覆盖关系" aria-label="Permalink to &quot;1.2 分层配置要有明确覆盖关系&quot;">​</a></h3><p>个人默认、项目局部和本次会话临时参数应形成清楚的优先级。通用偏好放在个人层，团队共识放在项目层，一次性实验留给启动参数或会话控制。</p><p>每一层都只承载适合它生命周期的信息。这样排查行为差异时，可以沿覆盖链找到真正生效的值，而不是在多个副本之间猜测。</p><p><img src="'+i+'" alt="图 1：个人、项目与会话配置的覆盖关系"></p><h2 id="二、记忆把经验带到下一次任务" tabindex="-1">二、记忆把经验带到下一次任务 <a class="header-anchor" href="#二、记忆把经验带到下一次任务" aria-label="Permalink to &quot;二、记忆把经验带到下一次任务&quot;">​</a></h2><h3 id="_2-1-上下文、项目规则与记忆是三种时间尺度" tabindex="-1">2.1 上下文、项目规则与记忆是三种时间尺度 <a class="header-anchor" href="#_2-1-上下文、项目规则与记忆是三种时间尺度" aria-label="Permalink to &quot;2.1 上下文、项目规则与记忆是三种时间尺度&quot;">​</a></h3><p>当前会话上下文保存眼前的对话和工具结果；项目规则保存相对稳定的仓库约束；记忆保存跨任务仍可能有价值的经验。它们都能影响代理，但生命周期和可信度不同。</p><p>把临时错误日志写成长期记忆，会污染后续判断；把长期架构决策只留在一次会话里，又会让经验随线程结束而消失。</p><h3 id="_2-2-好记忆必须可定位、可验证、可更新" tabindex="-1">2.2 好记忆必须可定位、可验证、可更新 <a class="header-anchor" href="#_2-2-好记忆必须可定位、可验证、可更新" aria-label="Permalink to &quot;2.2 好记忆必须可定位、可验证、可更新&quot;">​</a></h3><p>值得保留的内容包括稳定目录边界、验证命令、已经确认的故障模式和团队工作流。记录时应带来源或文件位置，方便未来重新验证。</p><p>任何记忆都可能过期。依赖版本、远端状态、价格和产品能力等易变事实，应在使用时重新查询，而不是因为“记得”就当作当前真相。</p><h3 id="_2-3-自动沉淀也需要人类治理" tabindex="-1">2.3 自动沉淀也需要人类治理 <a class="header-anchor" href="#_2-3-自动沉淀也需要人类治理" aria-label="Permalink to &quot;2.3 自动沉淀也需要人类治理&quot;">​</a></h3><p>记忆系统可以从历史任务提炼经验，但提炼不等于绝对正确。需要控制写入范围、去除秘密、合并重复信息，并允许修正失效结论。长期价值来自高信噪比，而不是无限堆积。</p><p><img src="'+l+'" alt="图 2：上下文、规则与长期记忆的时间尺度"></p><h2 id="三、mcp-让代理连接外部世界" tabindex="-1">三、MCP 让代理连接外部世界 <a class="header-anchor" href="#三、mcp-让代理连接外部世界" aria-label="Permalink to &quot;三、MCP 让代理连接外部世界&quot;">​</a></h2><h3 id="_3-1-mcp-是工具协议-不是万能数据库" tabindex="-1">3.1 MCP 是工具协议，不是万能数据库 <a class="header-anchor" href="#_3-1-mcp-是工具协议-不是万能数据库" aria-label="Permalink to &quot;3.1 MCP 是工具协议，不是万能数据库&quot;">​</a></h3><p>Model Context Protocol 为代理提供统一的工具、资源和提示接口。一个 MCP 服务可以连接文档库、Issue 系统、数据库或内部平台，代理不必为每个系统学习完全不同的调用方式。</p><p>协议统一的是连接形式，并不自动保证数据正确、权限合理或工具安全。服务返回什么、允许写什么，仍由提供者和配置决定。</p><h3 id="_3-2-工具、资源与提示承担不同职责" tabindex="-1">3.2 工具、资源与提示承担不同职责 <a class="header-anchor" href="#_3-2-工具、资源与提示承担不同职责" aria-label="Permalink to &quot;3.2 工具、资源与提示承担不同职责&quot;">​</a></h3><p>工具用于执行带输入输出的动作，例如查询工单或创建记录；资源用于读取可寻址内容，例如规范文档和数据模式；提示用于提供可复用的任务模板。将静态知识伪装成动作，或把有副作用的操作藏在资源读取里，都会破坏边界。</p><h3 id="_3-3-接入前先画清数据与权限流" tabindex="-1">3.3 接入前先画清数据与权限流 <a class="header-anchor" href="#_3-3-接入前先画清数据与权限流" aria-label="Permalink to &quot;3.3 接入前先画清数据与权限流&quot;">​</a></h3><p>需要确认代理会向服务发送哪些内容，服务能访问哪些系统，凭据存在哪里，写操作是否需要批准，结果是否可能包含敏感信息。外部连接越强，最小权限越重要。</p><p><img src="'+s+'" alt="图 3：Codex 通过 MCP 连接工具、资源与外部系统"></p><h2 id="四、子代理用隔离换取并行与专注" tabindex="-1">四、子代理用隔离换取并行与专注 <a class="header-anchor" href="#四、子代理用隔离换取并行与专注" aria-label="Permalink to &quot;四、子代理用隔离换取并行与专注&quot;">​</a></h2><h3 id="_4-1-适合拆分的是独立、可交付子任务" tabindex="-1">4.1 适合拆分的是独立、可交付子任务 <a class="header-anchor" href="#_4-1-适合拆分的是独立、可交付子任务" aria-label="Permalink to &quot;4.1 适合拆分的是独立、可交付子任务&quot;">​</a></h3><p>代码搜索、测试分析、文档核对和互不重叠的模块实现，都可能并行推进。主代理负责总体目标和最终整合，子代理在更窄的上下文中完成明确产物。</p><p>如果两个任务频繁修改同一文件、共享大量未决设计，强行并行只会增加冲突和协调成本。</p><h3 id="_4-2-上下文隔离比增加人手更重要" tabindex="-1">4.2 上下文隔离比增加人手更重要 <a class="header-anchor" href="#_4-2-上下文隔离比增加人手更重要" aria-label="Permalink to &quot;4.2 上下文隔离比增加人手更重要&quot;">​</a></h3><p>每个子代理只接收完成任务所需的信息，可以减少无关历史对判断的干扰。它返回结论、证据或补丁，而不是把完整思考过程重新灌回主线程。</p><h3 id="_4-3-主代理不能外包验收责任" tabindex="-1">4.3 主代理不能外包验收责任 <a class="header-anchor" href="#_4-3-主代理不能外包验收责任" aria-label="Permalink to &quot;4.3 主代理不能外包验收责任&quot;">​</a></h3><p>子代理给出的结果仍需由主代理检查范围、冲突和验证证据。并行提高吞吐量，但不会自动保证整体一致。没有明确接口与验收条件的多代理系统，只是更快地产生互相矛盾的结果。</p><p><img src="'+n+'" alt="图 4：主代理分解、子代理隔离、主线程整合"></p><h2 id="五、skills-把经验封装成按需加载的流程" tabindex="-1">五、Skills 把经验封装成按需加载的流程 <a class="header-anchor" href="#五、skills-把经验封装成按需加载的流程" aria-label="Permalink to &quot;五、Skills 把经验封装成按需加载的流程&quot;">​</a></h2><h3 id="_5-1-skill-解决重复工作流问题" tabindex="-1">5.1 Skill 解决重复工作流问题 <a class="header-anchor" href="#_5-1-skill-解决重复工作流问题" aria-label="Permalink to &quot;5.1 Skill 解决重复工作流问题&quot;">​</a></h3><p>当一类任务反复出现，仅靠每次临时 Prompt 会不断遗漏步骤。Skill 可以把触发条件、执行流程、参考资料、脚本和模板组织成可复用能力。</p><p>它适合封装明确领域流程，例如发布前检查、特定框架迁移、固定格式报告或内部工具操作，而不是把所有常识塞进一个巨型说明。</p><h3 id="_5-2-渐进式披露控制上下文成本" tabindex="-1">5.2 渐进式披露控制上下文成本 <a class="header-anchor" href="#_5-2-渐进式披露控制上下文成本" aria-label="Permalink to &quot;5.2 渐进式披露控制上下文成本&quot;">​</a></h3><p>代理先看到 Skill 的名称和用途，只有任务匹配时才读取完整说明，再按需要读取引用资料或运行脚本。这样既能发现能力，又避免每次会话加载所有细节。</p><p>Skill 的入口说明应短而精确，参考材料按主题拆分，脚本负责稳定机械步骤。上下文里只出现当前任务真正需要的部分。</p><h3 id="_5-3-skill-要能验证而不是只会指导" tabindex="-1">5.3 Skill 要能验证而不是只会指导 <a class="header-anchor" href="#_5-3-skill-要能验证而不是只会指导" aria-label="Permalink to &quot;5.3 Skill 要能验证而不是只会指导&quot;">​</a></h3><p>优秀 Skill 不只告诉代理“应该注意什么”，还应给出输入要求、检查命令、失败处理和交付格式。越能把经验转成可验证动作，复用价值越高。</p><p><img src="'+h+'" alt="图 5：Skill 的发现、加载与按需引用"></p><h2 id="六、插件是能力的分发与组合单元" tabindex="-1">六、插件是能力的分发与组合单元 <a class="header-anchor" href="#六、插件是能力的分发与组合单元" aria-label="Permalink to &quot;六、插件是能力的分发与组合单元&quot;">​</a></h2><h3 id="_6-1-插件可以同时携带多种能力" tabindex="-1">6.1 插件可以同时携带多种能力 <a class="header-anchor" href="#_6-1-插件可以同时携带多种能力" aria-label="Permalink to &quot;6.1 插件可以同时携带多种能力&quot;">​</a></h3><p>插件通常不只是一段提示，它可以打包 Skills、MCP 服务、应用连接器和清单元数据。这样一套面向某个平台或工作流的能力，可以作为整体安装、更新和发现。</p><h3 id="_6-2-安装插件意味着扩大信任边界" tabindex="-1">6.2 安装插件意味着扩大信任边界 <a class="header-anchor" href="#_6-2-安装插件意味着扩大信任边界" aria-label="Permalink to &quot;6.2 安装插件意味着扩大信任边界&quot;">​</a></h3><p>需要检查来源、版本、包含的工具、网络访问和写入能力。尤其是能够连接 GitHub、知识库或生产系统的插件，必须确认授权范围和最终动作是否保留人工批准。</p><h3 id="_6-3-组合优于复制" tabindex="-1">6.3 组合优于复制 <a class="header-anchor" href="#_6-3-组合优于复制" aria-label="Permalink to &quot;6.3 组合优于复制&quot;">​</a></h3><p>如果团队已经有稳定的 MCP 服务和 Skill，插件应引用和组织这些能力，而不是再维护一份行为相近但逐渐漂移的副本。插件解决的是交付与组合，不应制造新的事实源。</p><p><img src="'+p+'" alt="图 6：插件对 Skills、MCP 与应用能力的打包"></p><h2 id="七、规则与-hooks-把治理放到动作边界" tabindex="-1">七、规则与 Hooks 把治理放到动作边界 <a class="header-anchor" href="#七、规则与-hooks-把治理放到动作边界" aria-label="Permalink to &quot;七、规则与 Hooks 把治理放到动作边界&quot;">​</a></h2><h3 id="_7-1-规则负责静态判断" tabindex="-1">7.1 规则负责静态判断 <a class="header-anchor" href="#_7-1-规则负责静态判断" aria-label="Permalink to &quot;7.1 规则负责静态判断&quot;">​</a></h3><p>规则可以根据命令前缀、工具类型或动作属性决定允许、询问或拒绝。它适合处理可提前分类的重复决策，例如只读 Git 命令直接运行，公开发布始终确认。</p><p>规则应尽量窄。过宽的允许项会让本来安全的前缀携带危险参数，过宽的拒绝项又会阻断正常工作。</p><h3 id="_7-2-hooks-负责在生命周期节点执行检查" tabindex="-1">7.2 Hooks 负责在生命周期节点执行检查 <a class="header-anchor" href="#_7-2-hooks-负责在生命周期节点执行检查" aria-label="Permalink to &quot;7.2 Hooks 负责在生命周期节点执行检查&quot;">​</a></h3><p>Hooks 可以在任务开始、工具调用前后或任务结束时触发脚本和校验。例如检查工作树状态、阻止秘密进入提交、运行格式验证或记录审计信息。</p><p>Hook 不是隐藏业务逻辑的地方。它应该快速、确定、失败可解释，并让用户知道为什么动作被阻止。</p><h3 id="_7-3-规则、hook-与批准构成三道闸门" tabindex="-1">7.3 规则、Hook 与批准构成三道闸门 <a class="header-anchor" href="#_7-3-规则、hook-与批准构成三道闸门" aria-label="Permalink to &quot;7.3 规则、Hook 与批准构成三道闸门&quot;">​</a></h3><p>规则先做静态筛选，Hook 检查当前状态，批准处理高影响例外。三者结合后，低风险操作可以流畅执行，高风险操作仍保持可见。</p><p><img src="'+c+'" alt="图 7：规则、Hooks 与人工批准的动作治理链"></p><h2 id="八、不要把所有扩展都装进同一层" tabindex="-1">八、不要把所有扩展都装进同一层 <a class="header-anchor" href="#八、不要把所有扩展都装进同一层" aria-label="Permalink to &quot;八、不要把所有扩展都装进同一层&quot;">​</a></h2><p>如果要改变默认模型或权限，用配置；如果要传承仓库约束，用 <code>AGENTS.md</code>；如果要保存跨任务经验，用记忆；如果要连接外部系统，用 MCP；如果要拆分独立工作，用子代理；如果要复用专业流程，用 Skill；如果要分发一组能力，用插件；如果要约束动作，用规则和 Hooks。</p><p>这套分层最大的价值，是出现问题时能找到责任边界。代理没读懂项目，不该先怪模型；工具拿不到数据，不该往 Prompt 里硬塞；流程反复漏步，也不该无限加长全局规则。</p><h2 id="九、构建扩展体系的推荐顺序" tabindex="-1">九、构建扩展体系的推荐顺序 <a class="header-anchor" href="#九、构建扩展体系的推荐顺序" aria-label="Permalink to &quot;九、构建扩展体系的推荐顺序&quot;">​</a></h2><p>先用项目规则固定最重要的边界，再把稳定运行偏好放进配置。重复任务出现后提炼 Skill，需要外部数据时接入最小权限 MCP。只有当任务真正独立时才增加子代理，当能力需要团队分发时再封装插件。最后用规则和 Hooks 把高风险动作拦在边界上。</p><p>这个顺序遵循一个简单原则：先让单代理在单项目里稳定，再逐步增加连接、并行和自动化。每增加一层能力，都同时增加相应的验证与治理。</p><h2 id="十、参考资料" tabindex="-1">十、参考资料 <a class="header-anchor" href="#十、参考资料" aria-label="Permalink to &quot;十、参考资料&quot;">​</a></h2><p><a href="https://coding.stormzhang.ai/codex/18-config" target="_blank" rel="noreferrer">Codex 系列第 18 篇：配置</a></p><p><a href="https://coding.stormzhang.ai/codex/19-memory" target="_blank" rel="noreferrer">Codex 系列第 19 篇：记忆</a></p><p><a href="https://coding.stormzhang.ai/codex/20-mcp" target="_blank" rel="noreferrer">Codex 系列第 20 篇：MCP</a></p><p><a href="https://coding.stormzhang.ai/codex/21-subagents" target="_blank" rel="noreferrer">Codex 系列第 21 篇：子代理</a></p><p><a href="https://coding.stormzhang.ai/codex/22-skills" target="_blank" rel="noreferrer">Codex 系列第 22 篇：Skills</a></p><p><a href="https://coding.stormzhang.ai/codex/23-plugins" target="_blank" rel="noreferrer">Codex 系列第 23 篇：插件</a></p><p><a href="https://coding.stormzhang.ai/codex/24-hooks" target="_blank" rel="noreferrer">Codex 系列第 24 篇：规则与 Hooks</a></p><p><a href="https://developers.openai.com/codex/" target="_blank" rel="noreferrer">OpenAI Codex 官方文档</a></p>',82)])])}const q=e(d,[["render",_]]);export{P as __pageData,q as default};
